// This data shape is intentionally independent of the UI so a future topic can
// reuse the same study renderer.
const documentation = {
  select: ["SELECT", "https://www.postgresql.org/docs/current/sql-select.html"],
  sorting: ["Sorting rows", "https://www.postgresql.org/docs/current/queries-order.html"],
  pagination: ["LIMIT and OFFSET", "https://www.postgresql.org/docs/current/queries-limit.html"],
  aggregates: ["Aggregate functions", "https://www.postgresql.org/docs/current/functions-aggregate.html"],
  grouping: ["Grouping rows", "https://www.postgresql.org/docs/current/queries-table-expressions.html#QUERIES-GROUP"],
  comparisons: ["Comparison functions and operators", "https://www.postgresql.org/docs/current/functions-comparison.html"],
  conditional: ["Conditional expressions", "https://www.postgresql.org/docs/current/functions-conditional.html"],
  joins: ["Table expressions and joins", "https://www.postgresql.org/docs/current/queries-table-expressions.html#QUERIES-JOIN"],
  sets: ["Combining queries", "https://www.postgresql.org/docs/current/queries-union.html"],
  subqueries: ["Subquery expressions", "https://www.postgresql.org/docs/current/functions-subquery.html"],
  ctes: ["WITH queries", "https://www.postgresql.org/docs/current/queries-with.html"],
  dml: ["Data manipulation", "https://www.postgresql.org/docs/current/dml.html"],
  upsert: ["INSERT and ON CONFLICT", "https://www.postgresql.org/docs/current/sql-insert.html"],
  constraints: ["Constraints", "https://www.postgresql.org/docs/current/ddl-constraints.html"],
  indexes: ["Indexes", "https://www.postgresql.org/docs/current/indexes.html"],
  explain: ["Using EXPLAIN", "https://www.postgresql.org/docs/current/using-explain.html"],
  transactions: ["Transactions", "https://www.postgresql.org/docs/current/tutorial-transactions.html"],
  isolation: ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"],
  locks: ["Explicit locking", "https://www.postgresql.org/docs/current/explicit-locking.html"],
  windows: ["Window functions", "https://www.postgresql.org/docs/current/tutorial-window.html"],
};

const c = (id, level, topic, question, memorize, technical, extra, plain, reference, example = "") => ({
  id, level, topic, question, memorize, technical, extra, plain, example,
  docsLabel: documentation[reference][0],
  docsUrl: documentation[reference][1],
});

export const cards = [
  // 1. SELECT
  c("select", 1, "SELECT", "What does SELECT do?", "SELECT retrieves a result set from one or more tables or query expressions.", "In PostgreSQL, SELECT describes a query. It can use FROM, WHERE, GROUP BY, HAVING, ORDER BY, LIMIT, and other clauses to determine the result rows.", "A plain SELECT does not modify stored rows, although a query can request row locks with a locking clause such as FOR UPDATE.", "It is how you ask the database for information.", "select"),
  c("select", 2, "SELECT", "How would you explain the major parts of a SELECT query?", "SELECT chooses the returned values; FROM supplies rows; WHERE filters them; and ORDER BY requests their presentation order.", "These clauses define query semantics, not a forced physical execution sequence. PostgreSQL’s planner can choose a different efficient plan as long as the result obeys the SQL rules.", "Without ORDER BY, SQL does not guarantee result order, even if the same order often appears during testing.", "Think: find rows, keep the useful ones, then shape the answer.", "select", "SELECT id, name\nFROM members\nWHERE active = true\nORDER BY name;"),
  c("select", 3, "SELECT", "Why is SELECT called declarative?", "SELECT is declarative: you state the result you want, while PostgreSQL’s optimizer chooses a valid way to obtain it.", "A SELECT may draw from tables, views, functions, joins, subqueries, and CTEs. Its target list may include expressions, aggregates, window functions, and scalar subqueries. The planner can push filters, reorder inner joins, or choose scan methods when that preserves semantics.", "A SELECT-list alias is normally available to ORDER BY and GROUP BY, but not WHERE at that query level because WHERE filters before the output list is formed.", "You describe the destination; PostgreSQL works out a safe route.", "select", "SELECT price * quantity AS line_total\nFROM order_lines\nWHERE order_id = 42\nORDER BY line_total DESC;"),

  // 2. WHERE
  c("where", 1, "WHERE", "What does WHERE do?", "WHERE filters rows by a condition, keeping only rows for which the condition is TRUE.", "WHERE applies to input rows before grouping and aggregate calculation in the query’s logical semantics. FALSE and UNKNOWN conditions are both excluded.", "Use IS NULL or IS NOT NULL to test nullness; = NULL does not test for a NULL value.", "It is the gate that decides which rows may continue through the query.", "select"),
  c("where", 2, "WHERE", "What belongs in a WHERE clause?", "Use WHERE for row-level predicates that express which source rows the query should consider.", "Predicates can use comparisons, Boolean operators, ranges, patterns, null tests, and subquery expressions. PostgreSQL can use an applicable index when the predicate, statistics, and cost estimates make that cheaper than a sequential scan.", "A SELECT-list alias normally cannot be used in WHERE. Repeat the expression or use a subquery/CTE when an alias must be filtered.", "WHERE narrows the raw ingredients before you make a summary from them.", "select", "SELECT id, name\nFROM members\nWHERE active = true\n  AND joined_at >= date '2026-01-01';"),
  c("where", 3, "WHERE", "Which WHERE details affect performance and correctness?", "Write the intended predicate clearly first, remember it uses three-valued logic, then use EXPLAIN ANALYZE to verify how PostgreSQL evaluates it.", "A function or cast applied to an indexed column can prevent a simple index condition unless an expression index matches. Selectivity, parameter types, statistics, and correlation affect planning. In an outer join, a WHERE predicate on the nullable side can remove rows that an ON predicate would preserve.", "Do not add conditions merely because they look selective: an incorrect filter is not an optimization.", "A clear filter tells PostgreSQL what you mean; an index can then become a shortcut.", "select", "CREATE INDEX users_lower_email_idx ON users (lower(email));\n\nSELECT * FROM users\nWHERE lower(email) = lower($1);"),

  // 3. Sorting and pagination
  c("sorting-pagination", 1, "SORTING & PAGINATION", "Why are ORDER BY and LIMIT important?", "ORDER BY requests a result sequence, and LIMIT restricts how many rows are returned.", "Without ORDER BY, SQL does not guarantee row order. LIMIT applies to the result after the requested ordering, if any.", "OFFSET skips rows, but it is meaningful for a stable user-facing sequence only with an explicit ordering.", "First line the answers up, then take the number you need.", "pagination"),
  c("sorting-pagination", 2, "SORTING & PAGINATION", "How should you paginate a PostgreSQL query?", "Use ORDER BY with LIMIT; use OFFSET only with stable ordering, and prefer keyset pagination for large or changing result sets.", "LIMIT restricts rows. OFFSET discards a number of sorted rows before returning the limit. Inserts or deletes between requests can make OFFSET pagination skip or duplicate rows; a keyset predicate continues after the last seen sort tuple.", "Include a unique tiebreaker, usually the primary key, when the primary sort key is not unique.", "For long lists, continue after the last thing you saw instead of counting past every earlier thing.", "pagination", "SELECT id, created_at\nFROM events\nWHERE (created_at, id) < ($1, $2)\nORDER BY created_at DESC, id DESC\nLIMIT 20;"),
  c("sorting-pagination", 3, "SORTING & PAGINATION", "What are the performance caveats of pagination?", "Efficient pagination needs an index aligned with the filtering and ordering; OFFSET still makes PostgreSQL visit and discard preceding qualifying rows.", "A B-tree can support an ordered scan when the requested order and conditions match it. Keyset pagination expresses a seek from a known tuple and can continue from an index position, so its work does not grow linearly with the page number in the same way.", "PostgreSQL sorts NULL values last by default for ASC and first for DESC; specify NULLS FIRST or NULLS LAST when placement matters.", "Sorting arranges the books; keyset pagination puts your finger where you stopped reading.", "sorting", "CREATE INDEX events_feed_idx\n  ON events (created_at DESC, id DESC);\n\nSELECT id, created_at\nFROM events\nWHERE (created_at, id) < ($1, $2)\nORDER BY created_at DESC, id DESC\nLIMIT 20;"),

  // 4. DISTINCT
  c("distinct", 1, "DISTINCT", "What does DISTINCT do?", "DISTINCT removes duplicate result rows from a SELECT result.", "SELECT DISTINCT compares all selected expressions and returns one row for each equal combination.", "DISTINCT changes the query result; it does not add a uniqueness rule to the table.", "It turns repeated identical answers into one answer.", "select"),
  c("distinct", 2, "DISTINCT", "What is DISTINCT ON in PostgreSQL?", "DISTINCT ON is a PostgreSQL extension that keeps the first row of each group of equal expressions, so ORDER BY must decide which row is first.", "DISTINCT ON expressions must match the leftmost ORDER BY expressions. Further ORDER BY expressions choose the retained row within each group.", "Standard SQL has DISTINCT but not DISTINCT ON; ROW_NUMBER in a subquery is a portable alternative.", "Keep one row per label, and use the sort order to decide which one wins.", "select", "SELECT DISTINCT ON (customer_id)\n  customer_id, placed_at, total\nFROM orders\nORDER BY customer_id, placed_at DESC;"),
  c("distinct", 3, "DISTINCT", "When is DISTINCT a warning sign?", "Use DISTINCT when deduplicating is part of the requested result; do not use it to hide a join that multiplied rows unexpectedly.", "Duplicate elimination generally needs a sort or hash-based step. If a join condition is incomplete or a many-to-many relationship was not intended, DISTINCT can conceal the logic error and add work.", "For duplicate elimination, PostgreSQL considers two NULL values not distinct even though NULL = NULL is UNKNOWN in a normal comparison.", "It is a valid cleanup tool, not tape for a broken join.", "select", "-- Intentional: list each department once\nSELECT DISTINCT department\nFROM employees\nORDER BY department;"),

  // 5. Aggregates
  c("aggregates", 1, "AGGREGATES", "What is an aggregate function?", "An aggregate function calculates one value from a set of input rows, such as COUNT, SUM, AVG, MIN, or MAX.", "Aggregates collapse multiple input rows into one result per group. Without GROUP BY, the filtered input is one group.", "Except for COUNT, most PostgreSQL aggregates return NULL for no input rows; COUNT returns zero.", "It summarizes many rows into one number or value.", "aggregates"),
  c("aggregates", 2, "AGGREGATES", "What is the difference between COUNT(*) and COUNT(column)?", "COUNT(*) counts input rows; COUNT(column) counts only rows where that expression is not NULL.", "COUNT(DISTINCT expression) counts distinct non-NULL values. PostgreSQL also supports FILTER, which gives an individual aggregate its own condition.", "COUNT(*) does not mean PostgreSQL can always answer from metadata: under MVCC it must respect row visibility.", "COUNT(*) counts people in the room; COUNT(email) counts people who handed you an email address.", "aggregates", "SELECT\n  COUNT(*) AS all_rows,\n  COUNT(email) AS rows_with_email,\n  COUNT(*) FILTER (WHERE active) AS active_rows\nFROM members;"),
  c("aggregates", 3, "AGGREGATES", "What aggregate details are useful to know?", "Aggregates operate on filtered and grouped input, ignore NULL inputs except where documented otherwise, and may support DISTINCT, ORDER BY inside the call, or FILTER.", "Order-sensitive aggregates such as string_agg and array_agg need ORDER BY inside the aggregate call; otherwise their input order is unspecified. PostgreSQL also provides statistical and ordered-set aggregates. Aggregates cannot generally be nested at the same query level.", "COALESCE(SUM(amount), 0) can be right when an empty set should display as zero, but that is a business choice, not an inherent SQL rule.", "An aggregate is a summary machine: be explicit about its input and what an empty group means.", "aggregates", "SELECT customer_id,\n  string_agg(product_name, ', ' ORDER BY product_name) AS products\nFROM order_lines\nGROUP BY customer_id;"),

  // 6. GROUP BY
  c("group-by", 1, "GROUP BY", "What does GROUP BY do?", "GROUP BY forms groups of rows so aggregates can return one result for each group.", "A grouped query returns one row per group unless later operations change that. Without GROUP BY, an aggregate query treats all filtered input rows as one group.", "GROUP BY places NULL values together in one group.", "It puts similar rows into piles so you can calculate one summary per pile.", "grouping"),
  c("group-by", 2, "GROUP BY", "Why can’t you select any column in a GROUP BY query?", "Each selected expression must be an aggregate, appear in GROUP BY, or be functionally dependent on grouped columns under PostgreSQL’s rules.", "Grouping produces one output row for each group, so an ungrouped column would be ambiguous if a group contains several values. PostgreSQL recognizes some functional dependencies, such as a table primary key determining other table columns.", "You can group by expressions, not only bare columns.", "Once several rows become one group, PostgreSQL needs to know which single value you mean.", "grouping", "SELECT department, COUNT(*) AS headcount\nFROM employees\nWHERE active\nGROUP BY department;"),
  c("group-by", 3, "GROUP BY", "How would you explain or optimize a grouped query?", "Filter rows with WHERE before grouping and inspect the plan, because PostgreSQL can implement grouping with hashing or sorting.", "HashAggregate groups in memory, possibly spilling or batching; GroupAggregate consumes suitably sorted input. The planner chooses based on estimates and paths. GROUPING SETS, ROLLUP, and CUBE compute multiple grouping levels in one query shape.", "The grouping expression defines identity: grouping a formatted value or cast can deliberately change which rows are grouped together.", "Make the crowd smaller before you count it, then let PostgreSQL arrange the groups efficiently.", "grouping", "SELECT region, product, SUM(amount) AS revenue\nFROM sales\nGROUP BY ROLLUP (region, product)\nORDER BY region, product;"),

  // 7. HAVING
  c("having", 1, "HAVING", "What does HAVING do?", "HAVING filters groups after GROUP BY and aggregation; WHERE filters individual rows before grouping.", "A HAVING condition can use aggregate results, such as COUNT(*) or SUM(amount), because it is evaluated on formed groups.", "HAVING without GROUP BY filters the single implicit group produced by an aggregate query.", "WHERE checks each item before making piles; HAVING checks each finished pile.", "grouping"),
  c("having", 2, "HAVING", "When should a condition go in WHERE versus HAVING?", "Put row-level conditions in WHERE and aggregate-dependent conditions in HAVING, so fewer rows reach the grouping step.", "A condition on grouping columns can often be written in either place for an inner query, but WHERE normally communicates intent and enables earlier filtering. Conditions on COUNT, SUM, AVG, or another aggregate belong in HAVING.", "Use an aggregate FILTER clause when one aggregate needs a different condition from the query as a whole.", "Remove unsuitable ingredients before making piles; discard unsuitable piles after you count them.", "grouping", "SELECT department, COUNT(*) AS headcount\nFROM employees\nWHERE active\nGROUP BY department\nHAVING COUNT(*) >= 5;"),
  c("having", 3, "HAVING", "What technical details matter for HAVING?", "HAVING is a group predicate, so non-aggregate references must follow grouping rules; PostgreSQL can push safe conditions down, but authors should place predicates at their intended semantic level.", "A grouped query evaluates HAVING once per group. Aggregate results are unavailable at WHERE time, so filter a named aggregate in an outer query or CTE. PostgreSQL does not generally allow a SELECT-list alias in HAVING.", "Repeat the expression in HAVING or stage the result—do not depend on alias visibility that SQL does not provide.", "HAVING judges summaries, so if you need the summary’s name, make it first and then query it.", "grouping", "SELECT *\nFROM (\n  SELECT department, COUNT(*) AS headcount\n  FROM employees\n  GROUP BY department\n) AS counts\nWHERE headcount >= 5;"),

  // 8. NULL
  c("null", 1, "NULL", "What is NULL in SQL?", "NULL represents an unknown, missing, or inapplicable value; it is not zero, an empty string, or the word 'NULL'.", "SQL uses three-valued logic: comparisons involving NULL normally evaluate to UNKNOWN. WHERE retains only TRUE, so it excludes both FALSE and UNKNOWN.", "Use IS NULL or IS NOT NULL, not = NULL or <> NULL.", "NULL means 'we do not have a known value here.'", "comparisons"),
  c("null", 2, "NULL", "How does three-valued logic affect SQL conditions?", "A predicate can be TRUE, FALSE, or UNKNOWN. AND, OR, and NOT propagate UNKNOWN according to three-valued logic, and WHERE keeps only TRUE.", "For example, salary > 1000 is UNKNOWN when salary is NULL. Use IS DISTINCT FROM or IS NOT DISTINCT FROM when you need null-safe inequality or equality semantics.", "NOT IN can be surprising: a NULL in its list or subquery can make a non-match UNKNOWN. NOT EXISTS is often safer for anti-joins.", "Unknown answers do not pass a yes/no filter. Use null-aware operators when you need a definite comparison.", "comparisons", "SELECT id\nFROM employees\nWHERE manager_id IS NULL;\n\nSELECT * FROM changes\nWHERE old_value IS DISTINCT FROM new_value;"),
  c("null", 3, "NULL", "Which NULL details are worth knowing?", "NULL is a marker, not a value; normal equality is not null-safe, UNIQUE allows multiple NULLs by default, and outer joins deliberately introduce NULLs for unmatched sides.", "PostgreSQL provides IS [NOT] DISTINCT FROM and supports NULLS NOT DISTINCT on a unique constraint or index when nulls should be considered duplicates. Aggregates generally ignore NULL inputs, while COUNT(*) still counts their rows.", "COALESCE returns the first non-NULL argument, but replacing NULL in a predicate changes semantics and can change index use—use it because the fallback is intended.", "Treat NULL as unknown: comparisons need special grammar and every use needs a business meaning.", "comparisons", "CREATE TABLE contacts (\n  email text UNIQUE NULLS NOT DISTINCT\n);\n\nSELECT COALESCE(preferred_name, legal_name, 'Guest')\nFROM contacts;"),

  // 9. CASE
  c("case", 1, "CASE", "What is CASE in SQL?", "CASE is a conditional expression that returns a value based on ordered conditions or comparisons.", "The searched form tests WHEN predicates; the simple form compares one expression with each WHEN value. If nothing matches and ELSE is omitted, the result is NULL.", "CASE is an expression, so it can appear in SELECT, ORDER BY, aggregates, and other expression contexts.", "It is SQL’s 'if this, otherwise that' expression.", "conditional"),
  c("case", 2, "CASE", "How do you use CASE for conditional aggregation?", "CASE can produce a value conditionally, while an aggregate summarizes those values; that lets one query compute several conditional totals.", "All CASE result expressions must be convertible to a common output type. PostgreSQL normally evaluates only the branch needed for the result, although planning-time constant expressions can still raise errors in some cases.", "For a simple conditional aggregate, PostgreSQL’s FILTER syntax is often more direct than CASE.", "Give each row a value only when it qualifies, then add those values up.", "conditional", "SELECT\n  SUM(CASE WHEN status = 'paid' THEN amount ELSE 0 END) AS paid_total,\n  COUNT(*) FILTER (WHERE status = 'overdue') AS overdue_count\nFROM invoices;"),
  c("case", 3, "CASE", "What CASE caveats make an answer stronger?", "CASE is for conditional value selection, not procedural control flow; be careful with result types, NULL comparisons, and predicates that obscure indexed columns.", "Simple CASE uses equality, so CASE value WHEN NULL does not match a NULL value; use searched CASE with IS NULL. Applying CASE to an indexed column in WHERE can prevent a simple index condition unless an appropriate expression index exists or the predicate is rewritten.", "COALESCE, NULLIF, GREATEST, and LEAST are related conditional expressions but have their own NULL behavior.", "CASE is excellent for labels and calculations. For filtering, keep the condition direct when possible.", "conditional", "SELECT id,\n  CASE\n    WHEN closed_at IS NOT NULL THEN 'closed'\n    WHEN due_at < now() THEN 'overdue'\n    ELSE 'open'\n  END AS state\nFROM tickets;"),

  // 10. INNER JOIN
  c("inner-join", 1, "JOINS", "What is a JOIN?", "A JOIN combines rows from two table expressions according to a relationship condition; an INNER JOIN keeps only matching combinations.", "For each qualifying pair from its inputs, an inner join returns a combined row. Rows without a matching partner are omitted.", "JOIN ... ON is normally clearer than listing tables and a join predicate in WHERE.", "It connects rows that belong together; an inner join keeps only connections found on both sides.", "joins"),
  c("inner-join", 2, "INNER JOIN", "How would you join orders to customers?", "Join on the relationship key, usually a foreign key, and remember a one-to-many relationship correctly returns one customer row for each matching order.", "ON determines matching, while WHERE filters the joined result for an inner join. If the key is unique on one side, that side contributes at most one match for a row from the other side.", "An incomplete ON condition can create an unintended many-to-many multiplication of rows.", "Match each order’s customer ID to the customer with that ID.", "joins", "SELECT o.id, o.total, c.name\nFROM orders AS o\nJOIN customers AS c ON c.id = o.customer_id\nWHERE o.status = 'paid';"),
  c("inner-join", 3, "INNER JOIN", "What does a strong INNER JOIN explanation include?", "An inner join is a relational match defined by ON; its cardinality depends on data and constraints, and PostgreSQL can reorder inner joins when semantics permit.", "PostgreSQL can use nested loop, hash join, or merge join. Indexes and row-count estimates influence the choice. Foreign keys enforce valid references but do not automatically create an index on the referencing column.", "Use EXPLAIN ANALYZE to validate actual rows and estimate quality before forcing a join strategy.", "The match rule is the meaning; PostgreSQL can choose different efficient ways to perform the match.", "joins", "CREATE INDEX orders_customer_id_idx ON orders (customer_id);\n\nEXPLAIN ANALYZE\nSELECT c.name, o.total\nFROM customers c\nJOIN orders o ON o.customer_id = c.id;"),

  // 11. OUTER JOIN
  c("outer-join", 1, "OUTER JOIN", "What is an OUTER JOIN?", "An outer join preserves unmatched rows from one or both inputs and fills columns from the missing side with NULLs.", "LEFT JOIN preserves all left rows; RIGHT JOIN preserves all right rows; FULL JOIN preserves unmatched rows from both.", "LEFT JOIN is often easier to read than RIGHT JOIN because it follows the written table order.", "It keeps people who did not find a partner and leaves the missing partner fields blank.", "joins"),
  c("outer-join", 2, "OUTER JOIN", "Why can WHERE accidentally turn a LEFT JOIN into an inner join?", "A WHERE condition on a right-table column rejects NULL-extended unmatched rows, so it removes rows that the LEFT JOIN preserved.", "Put a condition that controls matching in ON when unmatched left rows must remain. Use WHERE for conditions that should filter the final result.", "To find left rows with no match, test a guaranteed non-NULL right column, usually its primary key, with IS NULL.", "If you filter out the blank partner fields afterward, you also filter out people without a partner.", "joins", "SELECT c.name, o.id\nFROM customers c\nLEFT JOIN orders o\n  ON o.customer_id = c.id\n AND o.status = 'paid';"),
  c("outer-join", 3, "OUTER JOIN", "What outer join details matter?", "Outer join semantics constrain reordering: PostgreSQL cannot freely move an outer join across other joins if that would change which rows are preserved or null-extended.", "ON first finds matches; then unmatched preserved-side rows are added with NULLs; then WHERE can remove them. FULL OUTER JOIN preserves both unmatched sets and needs careful null-aware predicates.", "Write the intended semantics directly rather than relying on planner simplification of null-rejecting predicates.", "A left join promises to keep the left list. Later filters can still throw people off it.", "joins", "SELECT c.id, c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.id IS NULL;"),

  // 12. CROSS and self joins
  c("cross-self", 1, "CROSS & SELF JOIN", "What are CROSS JOIN and self join?", "CROSS JOIN returns the Cartesian product of two inputs. A self join joins a table to another alias of the same table.", "A Cartesian product contains every possible pair, so its row count is the product of input counts. A self join uses aliases to distinguish two roles of one table.", "An unintended cross join is a common source of enormous result sets.", "CROSS JOIN pairs everything with everything; a self join lets a table relate to itself.", "joins"),
  c("cross-self", 2, "CROSS & SELF JOIN", "When would you use a self join?", "Use a self join when rows in one table relate to other rows in that table, such as an employee’s manager.", "Aliases are required because each table reference needs its own column qualifier. The join can be inner or outer depending on whether rows without the relationship should stay.", "A recursive CTE is often clearer than repeated self joins when a hierarchy has an unknown number of levels.", "It is like opening the same address book twice: once for employees and once for managers.", "joins", "SELECT e.name AS employee, m.name AS manager\nFROM employees e\nLEFT JOIN employees m ON m.id = e.manager_id;"),
  c("cross-self", 3, "CROSS & SELF JOIN", "What makes CROSS JOIN useful rather than dangerous?", "A cross join is correct when every combination is the intended domain, for example a reporting grid of dates and categories; otherwise make relationship conditions explicit.", "CROSS JOIN has no join condition. JOIN without a qualification is equivalent to CROSS JOIN in PostgreSQL, while INNER JOIN normally needs ON, USING, or NATURAL. A later WHERE can restrict combinations, but explicit JOIN ... ON communicates intent better.", "Estimate cardinality first: 1,000 rows crossed with 1,000 rows yields 1,000,000 combinations before filtering.", "Use it to deliberately build every pairing, never because you forgot how the tables connect.", "joins", "SELECT d.day, c.category\nFROM generate_series(date '2026-01-01', date '2026-01-07', interval '1 day') AS d(day)\nCROSS JOIN categories c;"),

  // 13. Set operations
  c("set-operations", 1, "SET OPERATIONS", "What are UNION, INTERSECT, and EXCEPT?", "They combine compatible SELECT results: UNION combines, INTERSECT keeps common rows, and EXCEPT keeps rows from the first result absent from the second.", "Corresponding queries need the same number of columns with compatible types. By default these operations remove duplicates.", "UNION ALL keeps duplicates and is usually cheaper when duplicate removal is not required.", "They merge lists, find overlap, or subtract one list from another.", "sets"),
  c("set-operations", 2, "SET OPERATIONS", "When would you choose UNION ALL instead of UNION?", "Choose UNION ALL when preserving duplicate rows is correct; choose UNION only when the result needs deduplication.", "UNION is shorthand for UNION DISTINCT and performs duplicate elimination across the combined output. ORDER BY or LIMIT after a set operation applies to the combined result unless parentheses create a separate subquery.", "Do not use UNION just to hide unexpected duplicates from a join or source data; understand why they exist.", "UNION ALL stacks lists. UNION stacks them and removes repeated lines.", "sets", "SELECT email FROM leads\nUNION ALL\nSELECT email FROM customers\nORDER BY email;"),
  c("set-operations", 3, "SET OPERATIONS", "What technical nuance should you mention for set operations?", "Set operations compare whole output rows using duplicate semantics, while ALL variants use multiset behavior: UNION ALL appends, INTERSECT ALL keeps the minimum multiplicity, and EXCEPT ALL subtracts multiplicities.", "PostgreSQL evaluates UNION and INTERSECT left-to-right, with INTERSECT binding more tightly than UNION and EXCEPT; parentheses remove ambiguity. Their duplicate treatment considers NULLs equal for this purpose.", "When only existence is needed, EXISTS or a semi-join may express the intent more directly than materializing and deduplicating a wide result.", "Set operations can work with counts of identical cards, not just whether a card exists once.", "sets", "(SELECT id FROM active_users)\nINTERSECT\n(SELECT id FROM newsletter_subscribers);"),

  // 14. Subqueries
  c("subqueries", 1, "SUBQUERIES", "What is a subquery?", "A subquery is a query nested inside another SQL statement, used as a value, a row set, or a condition.", "A scalar subquery must return at most one row and one column when used where a single value is required; no rows yields NULL and multiple rows cause an error.", "A subquery in FROM is a derived table and needs an alias in PostgreSQL.", "It is a smaller question inside a larger question.", "subqueries"),
  c("subqueries", 2, "SUBQUERIES", "What is the difference between IN and EXISTS?", "IN compares a value against values returned by a subquery; EXISTS asks only whether the subquery returns at least one row.", "EXISTS is TRUE when at least one row is produced and does not depend on the subquery’s selected columns. IN has three-valued NULL behavior, so NOT IN can be UNKNOWN when NULL is present; NOT EXISTS avoids that anti-join trap.", "PostgreSQL can transform suitable IN or EXISTS forms into a semi-join, so write the form that expresses the intended meaning.", "IN asks 'is this on the list?' EXISTS asks 'can I find any matching record?' ", "subqueries", "SELECT c.id, c.name\nFROM customers c\nWHERE EXISTS (\n  SELECT 1\n  FROM orders o\n  WHERE o.customer_id = c.id\n);"),
  c("subqueries", 3, "SUBQUERIES", "What should you know about subquery placement and performance?", "A subquery can be scalar, row-valued, table-producing, or a predicate; correlated subqueries refer to outer values and may be transformed by PostgreSQL when semantics allow.", "The planner can flatten many simple subqueries, but LIMIT, aggregation, window functions, volatile expressions, or security barriers can prevent transformations. An explicit join is not automatically faster; EXPLAIN ANALYZE and suitable indexes decide the actual tradeoff.", "Use LATERAL when a FROM subquery or function must reference columns from earlier FROM items.", "A nested question can sometimes be folded into the main conversation, but not every nested question is safe to rearrange.", "subqueries", "SELECT c.name, latest.placed_at\nFROM customers c\nLEFT JOIN LATERAL (\n  SELECT placed_at FROM orders\n  WHERE customer_id = c.id\n  ORDER BY placed_at DESC\n  LIMIT 1\n) latest ON true;"),

  // 15. Correlated subqueries and EXISTS
  c("correlated-exists", 1, "CORRELATED SUBQUERY", "What is a correlated subquery?", "A correlated subquery references a column from the outer query, so its result can depend on the current outer row.", "The inner query is logically evaluated in the outer row’s context. EXISTS is a common correlated-subquery pattern.", "Correlation describes logic; PostgreSQL can transform the physical plan when that preserves semantics.", "The inner question changes depending on which outer row you are looking at.", "subqueries"),
  c("correlated-exists", 2, "CORRELATED SUBQUERY", "How do you find rows with no related rows safely?", "Use NOT EXISTS with a correlated equality predicate to express an anti-join, especially when nullable values are involved.", "NOT EXISTS is TRUE only when its subquery returns zero rows. Unlike NOT IN, it does not become UNKNOWN merely because a comparison source contains NULL.", "Index the inner relation’s matching key for efficient existence checks on large data sets.", "For each customer, ask: can I find even one order? Keep the customer only when the answer is no.", "subqueries", "SELECT c.id, c.name\nFROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o\n  WHERE o.customer_id = c.id\n);"),
  c("correlated-exists", 3, "CORRELATED SUBQUERY", "How do correlated subqueries relate to semi-joins and anti-joins?", "EXISTS is logically an existence predicate and PostgreSQL can often plan it as a semi-join; NOT EXISTS can often become an anti-join, avoiding duplicate multiplication from an ordinary join.", "A semi-join returns each outer row at most once based on whether a match exists, while an inner join returns a row for every matching pair. Use EXISTS when no related columns are needed and only existence matters.", "A correlated scalar subquery needs an aggregate, a deterministic LIMIT, or another rule when it could otherwise return more than one row.", "EXISTS answers a yes/no relationship question, so it avoids copying the outer row for every yes.", "subqueries", "SELECT p.id\nFROM products p\nWHERE EXISTS (\n  SELECT 1 FROM order_lines ol\n  WHERE ol.product_id = p.id\n    AND ol.quantity > 100\n);"),

  // 16. CTEs
  c("ctes", 1, "CTEs", "What is a CTE?", "A common table expression, or CTE, is a named temporary result defined by WITH for one SQL statement.", "A CTE can be referenced by the main query and, when declared RECURSIVE, by itself. Its name exists only for that statement.", "CTEs can be used with SELECT, INSERT, UPDATE, DELETE, or MERGE as the main statement.", "It is a named step inside one larger query.", "ctes"),
  c("ctes", 2, "CTEs", "When is a CTE useful?", "Use a CTE to name a meaningful query step, reuse a result within a statement, or express recursion; do not assume it always materializes or improves performance.", "Since PostgreSQL 12, a side-effect-free CTE used once can usually be folded into its parent query. MATERIALIZED can request materialization, while NOT MATERIALIZED can request folding when permitted.", "A data-modifying CTE executes once and to completion, and all sub-statements share the same snapshot.", "A CTE gives a long query labelled checkpoints, but PostgreSQL can still combine simple checkpoints efficiently.", "ctes", "WITH recent_orders AS (\n  SELECT * FROM orders\n  WHERE placed_at >= current_date - interval '30 days'\n)\nSELECT customer_id, COUNT(*)\nFROM recent_orders\nGROUP BY customer_id;"),
  c("ctes", 3, "CTEs", "How does a recursive CTE work?", "A recursive CTE has a non-recursive seed term UNION [ALL] a recursive term; PostgreSQL repeatedly evaluates the recursive term against prior iteration rows until none remain.", "Recursive queries are evaluated iteratively. UNION removes duplicate rows across iterations, while UNION ALL retains them and can require explicit cycle prevention. PostgreSQL supports SEARCH and CYCLE clauses to help order results and detect cycles.", "Use a depth limit or cycle rule when traversing graph-like data that may not be acyclic.", "Start with the top of the hierarchy, then repeatedly add the next layer until there is nothing new.", "ctes", "WITH RECURSIVE org AS (\n  SELECT id, manager_id, name, 0 AS depth\n  FROM employees WHERE manager_id IS NULL\n  UNION ALL\n  SELECT e.id, e.manager_id, e.name, o.depth + 1\n  FROM employees e JOIN org o ON e.manager_id = o.id\n)\nSELECT * FROM org;"),

  // 17. Data modification
  c("dml", 1, "DATA MODIFICATION", "What are INSERT, UPDATE, and DELETE?", "INSERT adds rows, UPDATE changes existing rows, and DELETE removes rows; they are SQL data-modification statements.", "Each statement can use a WHERE condition where relevant, and PostgreSQL can return affected rows with RETURNING.", "An UPDATE or DELETE without WHERE targets every row in its target table.", "They are the commands for adding, changing, and removing stored data.", "dml"),
  c("dml", 2, "DATA MODIFICATION", "Why is RETURNING useful in PostgreSQL?", "RETURNING returns values from rows inserted, updated, deleted, or merged, so an application can get generated IDs or changed values without a separate query.", "For INSERT and UPDATE, RETURNING sees new row values; for DELETE, it sees deleted row values. PostgreSQL also supports old and new row aliases in RETURNING for relevant statements.", "Use a transaction when several modifications must succeed or fail as one unit.", "It lets the change operation hand you the receipt immediately.", "dml", "UPDATE accounts\nSET last_seen_at = now()\nWHERE id = $1\nRETURNING id, last_seen_at;"),
  c("dml", 3, "DATA MODIFICATION", "What DML safety and concurrency details matter?", "DML operates on rows visible to its command under MVCC, acquires appropriate locks, enforces constraints, and needs explicit predicates and transaction boundaries for correctness.", "UPDATE ... FROM can join other tables, but if its join produces multiple source rows for one target row, only one is used and the choice is not predictable—make the source one-to-one. DELETE ... USING has similar join power. MERGE has different concurrency behavior from ON CONFLICT.", "For a high-impact UPDATE or DELETE, first validate the same predicate with a SELECT in the intended transaction context.", "Data changes are powerful: name the target precisely, let constraints protect you, and group related changes in a transaction.", "dml", "DELETE FROM sessions\nWHERE expires_at < now()\nRETURNING id, user_id;"),

  // 18. Upserts
  c("upsert", 1, "UPSERT", "What is an upsert in PostgreSQL?", "An upsert is INSERT ... ON CONFLICT, which inserts a row or handles a unique or exclusion conflict with DO NOTHING or DO UPDATE.", "The conflict target identifies a unique index or constraint to arbitrate the conflict. DO UPDATE can refer to the proposed row as EXCLUDED.", "ON CONFLICT is PostgreSQL syntax; other databases have related features with different behavior.", "Try to add the row; if its unique identity exists, skip it or update it.", "upsert"),
  c("upsert", 2, "UPSERT", "How does ON CONFLICT DO UPDATE work?", "It attempts the insert atomically; on a matching unique or exclusion conflict, it locks the conflicting row and runs the specified update if its WHERE condition permits it.", "ON CONFLICT DO UPDATE guarantees an atomic INSERT-or-UPDATE outcome for each proposed row under high concurrency. EXCLUDED contains proposed insertion values after BEFORE INSERT trigger effects.", "One INSERT cannot affect the same existing row more than once; duplicate proposed conflict keys can cause a cardinality violation.", "It is a race-safe 'create this record, otherwise refresh it' operation.", "upsert", "INSERT INTO inventory (sku, quantity)\nVALUES ($1, $2)\nON CONFLICT (sku) DO UPDATE\nSET quantity = inventory.quantity + EXCLUDED.quantity\nRETURNING sku, quantity;"),
  c("upsert", 3, "UPSERT", "What upsert caveats should you know?", "ON CONFLICT needs a matching unique or exclusion arbiter; DO NOTHING may omit its target, but DO UPDATE needs one and can still fail other constraints.", "PostgreSQL can infer a matching unique index from a column/expression conflict target. DO UPDATE locks a conflicting row even if its WHERE condition later prevents an update; that row is not returned by RETURNING. ON CONFLICT is not interchangeable with MERGE.", "Choose a conflict target that encodes the real business identity. A random surrogate key alone cannot detect a duplicate natural entity.", "An upsert is safe only if the database has a rule for what 'the same record' means.", "upsert", "INSERT INTO user_settings (user_id, theme)\nVALUES ($1, 'dark')\nON CONFLICT ON CONSTRAINT user_settings_user_id_key\nDO UPDATE SET theme = EXCLUDED.theme;"),

  // 19. Constraints and keys
  c("constraints", 1, "CONSTRAINTS & KEYS", "What are primary keys, foreign keys, and constraints?", "Constraints are database-enforced rules. A primary key uniquely identifies a row and is not NULL; a foreign key requires related values to exist in another table.", "PostgreSQL also supports NOT NULL, UNIQUE, CHECK, and exclusion constraints. A primary key automatically creates a unique B-tree index.", "A foreign key protects valid references but does not automatically index its referencing columns.", "Constraints are rules the database enforces so bad data cannot quietly enter.", "constraints"),
  c("constraints", 2, "CONSTRAINTS & KEYS", "How do UNIQUE and PRIMARY KEY differ?", "Both enforce uniqueness, but a table has at most one primary key, its columns are implicitly NOT NULL, and it is the conventional foreign-key target; UNIQUE permits NULLs by default.", "PostgreSQL automatically creates a unique B-tree index for primary-key and unique constraints. A composite key makes uniqueness apply to the column combination, not each column separately.", "Use CHECK for a row-level invariant such as amount >= 0; it must not rely on other table rows or mutable external state.", "A primary key is the row’s required ID. A unique rule says another label must not repeat, but it may be absent.", "constraints", "CREATE TABLE orders (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  customer_id bigint NOT NULL REFERENCES customers(id),\n  external_ref text UNIQUE,\n  amount numeric NOT NULL CHECK (amount >= 0)\n);"),
  c("constraints", 3, "CONSTRAINTS & KEYS", "What constraint details make an answer stronger?", "Constraints express integrity declaratively; PostgreSQL enforces them transactionally, and some can be DEFERRABLE so they are checked at transaction end rather than after each statement.", "CHECK passes when its expression is TRUE or NULL, so pair it with NOT NULL when NULL must be rejected. A foreign key’s ON DELETE/ON UPDATE action—RESTRICT, CASCADE, SET NULL, or SET DEFAULT—defines treatment of dependent rows.", "Do not use CHECK to enforce cross-row uniqueness or references; use UNIQUE, EXCLUDE, FOREIGN KEY, triggers, or a different model as appropriate.", "Put important data rules where every application path must obey them: in the database schema.", "constraints", "CREATE TABLE line_items (\n  order_id bigint REFERENCES orders(id) ON DELETE CASCADE,\n  line_no integer NOT NULL,\n  quantity integer NOT NULL CHECK (quantity > 0),\n  PRIMARY KEY (order_id, line_no)\n);"),

  // 20. Indexes
  c("indexes", 1, "INDEXES", "What is a database index?", "An index is an auxiliary data structure that can help PostgreSQL find rows or provide ordering without scanning an entire table.", "PostgreSQL automatically creates indexes for primary-key and unique constraints. Other indexes must be created explicitly.", "Indexes speed some reads but add storage and maintenance work to inserts, updates, and deletes.", "It is like a book index: faster lookup, but someone must keep it updated.", "indexes"),
  c("indexes", 2, "INDEXES", "How do you choose a PostgreSQL index?", "Choose indexes from actual query predicates, joins, and ordering; a B-tree is the default choice for many equality, range, and ordering queries.", "Composite B-tree indexes are most useful when query conditions match useful leading columns, although PostgreSQL can sometimes use later columns. Other built-in index types include Hash, GiST, SP-GiST, GIN, and BRIN for different data and operators.", "Use EXPLAIN ANALYZE to verify benefit; the planner may correctly prefer a sequential scan when it estimates that cheaper.", "Build the index around how you look things up, not a generic checklist of columns.", "indexes", "CREATE INDEX orders_customer_placed_idx\n  ON orders (customer_id, placed_at DESC);\n\nSELECT * FROM orders\nWHERE customer_id = $1\nORDER BY placed_at DESC\nLIMIT 20;"),
  c("indexes", 3, "INDEXES", "What advanced index points are useful?", "An index helps only when its access method and operator class support the query, selectivity and table size justify it, and the cost model favors it; indexes are a workload tradeoff.", "A partial index contains rows meeting a predicate; an expression index contains a computed expression; INCLUDE columns can enable index-only scans without being search keys. Index-only scans still depend on the visibility map and can visit the heap. Predicate implication matters for partial indexes.", "Referencing foreign-key columns are often good index candidates because parent deletes and updates need to find matching child rows.", "The best index is a small, well-shaped shortcut for a frequent access path, not a duplicate of the table.", "indexes", "CREATE INDEX orders_open_recent_idx\n  ON orders (customer_id, placed_at DESC)\n  INCLUDE (total)\n  WHERE status = 'open';"),

  // 21. EXPLAIN
  c("explain", 1, "QUERY PLANS", "What are EXPLAIN and EXPLAIN ANALYZE?", "EXPLAIN shows PostgreSQL’s planned execution strategy. EXPLAIN ANALYZE runs the statement and reports actual execution statistics.", "The plan is a tree of operations such as scans, joins, sorts, and aggregates, with estimated costs and row counts.", "EXPLAIN ANALYZE executes the statement, so use caution with modifications and a transaction you can roll back when appropriate.", "EXPLAIN shows PostgreSQL’s route; EXPLAIN ANALYZE shows what happened on that route.", "explain"),
  c("explain", 2, "QUERY PLANS", "What should you look for in EXPLAIN ANALYZE?", "Compare estimated rows with actual rows, identify expensive nodes and loops, and look for unexpected scans, sorts, spills, or join strategies.", "Actual time is reported per node and loop; parent time is not simply added across all nodes. BUFFERS exposes buffer activity, while VERBOSE and SETTINGS add further diagnostic context.", "Large estimate errors often point to stale statistics, data skew, correlated columns, or predicates the planner cannot estimate well.", "Find where PostgreSQL expected a few rows but got many, or where it did much more work than the question seemed to need.", "explain", "EXPLAIN (ANALYZE, BUFFERS)\nSELECT *\nFROM orders\nWHERE customer_id = 42\nORDER BY placed_at DESC\nLIMIT 20;"),
  c("explain", 3, "QUERY PLANS", "How do you use EXPLAIN responsibly?", "Measure a representative query with EXPLAIN ANALYZE, interpret estimates, actuals, and buffer work, then fix the cause—query shape, indexes, statistics, or schema—rather than forcing a plan blindly.", "Planner costs are relative units, not milliseconds. ANALYZE updates statistics, and extended statistics can help correlated columns. Prepared-plan choice, parameters, cache state, and concurrent load can all affect observed behavior.", "A sequential scan is not inherently bad: for a large fraction of a small table or a low-selectivity predicate it can be optimal.", "Treat the plan as evidence. Improve why PostgreSQL chose poorly, not just the choice you saw once.", "explain", "BEGIN;\nEXPLAIN (ANALYZE, BUFFERS)\nUPDATE accounts\nSET status = 'inactive'\nWHERE last_seen_at < current_date - 365;\nROLLBACK;"),

  // 22. Transactions and ACID
  c("transactions", 1, "TRANSACTIONS & ACID", "What is a transaction, and what does ACID mean?", "A transaction groups operations into one unit of work. ACID means atomicity, consistency, isolation, and durability.", "COMMIT makes a transaction’s changes durable; ROLLBACK discards its changes. Without an explicit transaction block, PostgreSQL treats each individual statement as a transaction.", "Consistency means declared rules hold across the transition; it does not prove that application business logic is correct.", "A transaction is an all-or-nothing bundle with rules for safe sharing and surviving failure.", "transactions"),
  c("transactions", 2, "TRANSACTIONS & ACID", "Why should a money transfer use a transaction?", "A transfer needs one transaction so the debit and credit both commit or both roll back; constraints and error handling protect the invariant.", "PostgreSQL uses MVCC, so transactions see a snapshot determined by isolation level while writes are coordinated with locks. After an error in an explicit transaction, PostgreSQL marks it aborted until ROLLBACK or ROLLBACK TO SAVEPOINT.", "Keep transactions short to reduce lock duration and contention.", "Do not let money leave one account unless it reaches the other in the same all-or-nothing package.", "transactions", "BEGIN;\nUPDATE accounts SET balance = balance - 100 WHERE id = 1;\nUPDATE accounts SET balance = balance + 100 WHERE id = 2;\nCOMMIT;"),
  c("transactions", 3, "TRANSACTIONS & ACID", "What ACID caveats are worth explaining?", "ACID guarantees apply at the transaction boundary, but isolation has selectable strength and applications must still define and enforce their invariants under concurrency.", "PostgreSQL durability relies on write-ahead logging and commit processing, subject to configuration such as synchronous_commit. Savepoints permit partial rollback. An external effect such as sending email cannot be atomically committed with the database without a coordination pattern such as an outbox.", "Do not hold a transaction open during slow user interaction or remote calls unless the design explicitly needs it.", "The database can make its own changes all-or-nothing; coordinating the outside world needs more design.", "transactions", "BEGIN;\nSAVEPOINT before_optional_step;\n-- optional operation\nROLLBACK TO SAVEPOINT before_optional_step;\nCOMMIT;"),

  // 23. Isolation, locks, and deadlocks
  c("isolation-locks", 1, "ISOLATION, LOCKS & DEADLOCKS", "What are isolation levels, locks, and deadlocks?", "Isolation levels control how concurrent transactions observe data. Locks coordinate conflicting operations. A deadlock is a cycle of transactions waiting on one another.", "PostgreSQL detects a deadlock and aborts one transaction so the others can proceed. An application should retry the aborted transaction when retrying is safe.", "PostgreSQL’s default Read Committed level gives each statement a fresh snapshot, not a fixed snapshot for the whole transaction.", "Isolation controls what you see; locks prevent conflicting changes; a deadlock is two people waiting for the other to move.", "isolation"),
  c("isolation-locks", 2, "ISOLATION, LOCKS & DEADLOCKS", "How do you reduce deadlocks?", "Keep transactions short, access shared rows in a consistent order, index lookup predicates, and retry transactions that fail with a deadlock or serialization error.", "PostgreSQL uses row-level and table-level locks while MVCC lets many readers and writers proceed. Conflicting updates to the same row wait; different lock orders across several rows or tables create deadlock risk.", "Do not simply increase a timeout: diagnose the cycle and make the access pattern consistent.", "If everyone picks up resources in the same order, they are less likely to block each other in a circle.", "locks", "SELECT id\nFROM accounts\nWHERE id IN ($1, $2)\nORDER BY id\nFOR UPDATE;"),
  c("isolation-locks", 3, "ISOLATION, LOCKS & DEADLOCKS", "How do PostgreSQL isolation levels differ?", "Read Committed sees a fresh snapshot per statement; Repeatable Read uses one transaction snapshot; Serializable can abort transactions to preserve an outcome equivalent to serial execution.", "PostgreSQL treats Read Uncommitted as Read Committed because MVCC does not expose dirty reads. Serializable Snapshot Isolation can raise serialization_failure without traditional blocking, so whole-transaction retry logic is required. SELECT FOR UPDATE and related clauses lock selected rows against conflicting row-level operations.", "Use the lowest isolation that meets the invariant, then prove the invariant under concurrency. Stronger isolation can trade retries or blocking for stronger guarantees.", "More isolation gives a steadier picture, but sometimes PostgreSQL asks one transaction to try again.", "isolation", "BEGIN ISOLATION LEVEL SERIALIZABLE;\n-- Read and write one concurrent invariant\nCOMMIT;\n-- Retry the whole transaction on SQLSTATE 40001"),

  // 24. Window functions
  c("window-functions", 1, "WINDOW FUNCTIONS", "What is a window function?", "A window function calculates a value across related rows while keeping one output row for each input row.", "It uses an OVER clause to define a window, optionally with PARTITION BY, ORDER BY, and a frame. Unlike GROUP BY, it does not collapse rows.", "Common examples are ROW_NUMBER, RANK, LAG, LEAD, and aggregates used with OVER.", "It lets each row see a group summary or nearby rows without disappearing into one summary row.", "windows"),
  c("window-functions", 2, "WINDOW FUNCTIONS", "How do ROW_NUMBER, RANK, and DENSE_RANK differ?", "ROW_NUMBER assigns consecutive numbers; RANK gives tied rows the same rank and leaves gaps; DENSE_RANK gives tied rows the same rank without gaps.", "PARTITION BY restarts the calculation per partition, and ORDER BY determines ranking. If the ordering is not unique, ROW_NUMBER among peer rows is nondeterministic unless you add a tiebreaker.", "Window functions are evaluated after WHERE, GROUP BY, and HAVING, so filter their output in an outer query or another query level.", "They are three ways to number a leaderboard when scores tie.", "windows", "SELECT customer_id, placed_at, total,\n  ROW_NUMBER() OVER (\n    PARTITION BY customer_id\n    ORDER BY placed_at DESC, id DESC\n  ) AS order_number\nFROM orders;"),
  c("window-functions", 3, "WINDOW FUNCTIONS", "What is a window frame and why does it matter?", "A window frame defines which rows within the current partition and order contribute to frame-sensitive functions such as running aggregates, FIRST_VALUE, LAST_VALUE, and NTH_VALUE.", "With ORDER BY, PostgreSQL’s default frame runs from the partition start through the last peer of the current row, which can surprise users of LAST_VALUE. Specify ROWS, RANGE, or GROUPS and explicit bounds when the intended frame matters.", "A window function cannot be nested inside another window function at the same query level, but a subquery or CTE can stage calculations.", "The partition is the whole group; the frame is the moving slice this row may look at.", "windows", "SELECT day, amount,\n  SUM(amount) OVER (\n    ORDER BY day\n    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n  ) AS running_total\nFROM daily_sales;"),
];

export const levels = [1, 2, 3];
